insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000062001', '40000000-0000-4000-8000-000000006200', 'Passo 2', 'Por partes, $\int xe^x dx=xe^x-\int e^x dx=e^x(x-1)+C$.', '2') on conflict do nothing;
