insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000062020', '40000000-0000-4000-8000-000000006202', 'Passo 1', 'Tome $u=x$, $dv=\cos x\,dx$. Então $v=\sin x$.', '1') on conflict do nothing;
