insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062030', '40000000-0000-4000-8000-000000006203', 'Escolha o método', 'Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006203' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062031', '40000000-0000-4000-8000-000000006203', 'Desenvolva a estratégia', 'Com $u=x$ e $dv=e^{2x}dx$, temos $v=e^{2x}/2$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006203' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062032', '40000000-0000-4000-8000-000000006203', 'Complete o cálculo', 'Subtraia $\frac12\int e^{2x}dx$ de $xe^{2x}/2$, obtendo $e^{2x}(x/2-1/4)+C$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006203' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062033', '40000000-0000-4000-8000-000000006203', 'Confira o resultado', 'Derive a expressão final. Se a derivada não reproduzir o integrando, revise principalmente o sinal do termo subtraído.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006203' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
