insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062111', '40000000-0000-4000-8000-000000006211', 'Desenvolva a estratégia', 'O fator repetido exige $A/x+B/(x+1)+D/(x+1)^2$. A identidade dos numeradores dá $A=1$, $B=-1$, $D=-1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006211' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062112', '40000000-0000-4000-8000-000000006211', 'Complete o cálculo', 'A primitiva de $-(x+1)^{-2}$ é $+(x+1)^{-1}$. Some esse termo aos dois logaritmos.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006211' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062113', '40000000-0000-4000-8000-000000006211', 'Confira o resultado', 'Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006211' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000062120', '40000000-0000-4000-8000-000000006212', 'Compare os graus do numerador e do denominador; se necessário, faça a divisão polinomial antes das frações parciais.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000062121', '40000000-0000-4000-8000-000000006212', 'Depois de encontrar os coeficientes, substitua-os de volta na identidade para conferir o numerador.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062120', '40000000-0000-4000-8000-000000006212', 'Escolha o método', 'Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062121', '40000000-0000-4000-8000-000000006212', 'Desenvolva a estratégia', 'Faça primeiro a divisão: $(x^2+1)/(x^2+x)=1+(1-x)/(x(x+1))$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062122', '40000000-0000-4000-8000-000000006212', 'Complete o cálculo', 'A parte própria é $1/x-2/(x+1)$. Integrando com o termo polinomial, resulta $x+\ln x-2\ln(x+1)+C$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062123', '40000000-0000-4000-8000-000000006212', 'Confira o resultado', 'Diferencie o resultado e observe o domínio dos logaritmos. Em intervalos que cruzam raízes do denominador, os módulos são importantes.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006212' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
