insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062151', '40000000-0000-4000-8000-000000006215', 'Desenvolva a estratégia', 'Separe $\sin x$ e use $\sin^2x=1-\cos^2x$. Com $u=\cos x$, $du=-\sin x dx$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006215' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
