insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000068071', '40000000-0000-4000-8000-000000006807', 'Depois de obter o raio, substitua cada extremo separadamente na série original.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006807' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068070', '40000000-0000-4000-8000-000000006807', 'Escolha o método', 'Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006807' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068071', '40000000-0000-4000-8000-000000006807', 'Desenvolva a estratégia', 'Se $x\ne0$, a razão dos módulos é $(n+1)|x|\to\infty$, causando divergência.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006807' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068072', '40000000-0000-4000-8000-000000006807', 'Complete o cálculo', 'Em $x=0$, todos os termos são zero. Só há convergência no centro, então $R=0$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006807' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068073', '40000000-0000-4000-8000-000000006807', 'Confira o resultado', 'Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006807' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000068080', '40000000-0000-4000-8000-000000006808', 'Aplique razão ou raiz ao coeficiente que multiplica a potência de $x$.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006808' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000068081', '40000000-0000-4000-8000-000000006808', 'Depois de obter o raio, substitua cada extremo separadamente na série original.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006808' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068080', '40000000-0000-4000-8000-000000006808', 'Escolha o método', 'Para séries de potências, determine primeiro o raio de convergência; os extremos do intervalo exigem testes separados.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006808' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068081', '40000000-0000-4000-8000-000000006808', 'Desenvolva a estratégia', 'O centro é $-2$ e a razão fornece raio $3$, com interior $(-5,1)$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006808' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068082', '40000000-0000-4000-8000-000000006808', 'Complete o cálculo', 'Nos extremos, os módulos são $1/n^2$ e somam uma série convergente. Ambos pertencem ao intervalo.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006808' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068083', '40000000-0000-4000-8000-000000006808', 'Confira o resultado', 'Não transfira automaticamente o resultado de um extremo para o outro: os sinais podem mudar a convergência.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006808' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000068090', '40000000-0000-4000-8000-000000006809', 'Escreva os primeiros termos da série ao redor do centro indicado antes de substituir valores.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006809' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000068091', '40000000-0000-4000-8000-000000006809', 'Para estimar erro, identifique a primeira potência omitida e a cota pedida pelo enunciado.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006809' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068090', '40000000-0000-4000-8000-000000006809', 'Escolha o método', 'Use a série conhecida ou calcule derivadas no centro, mantendo a potência e o fatorial correspondentes a cada ordem.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006809' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068091', '40000000-0000-4000-8000-000000006809', 'Desenvolva a estratégia', 'As derivadas de $e^x$ em zero valem $1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006809' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068092', '40000000-0000-4000-8000-000000006809', 'Complete o cálculo', 'A fórmula $f(0)+f''(0)x+f''''(0)x^2/2!$ dá $1+x+x^2/2$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006809' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068093', '40000000-0000-4000-8000-000000006809', 'Confira o resultado', 'Confira o termo constante avaliando a aproximação no centro; ele deve coincidir com o valor da função nesse ponto.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006809' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
