insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068101', '40000000-0000-4000-8000-000000006810', 'Desenvolva a estratégia', 'As derivadas de ordem zero a três em zero são $0,1,0,-1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006810' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
