insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068110', '40000000-0000-4000-8000-000000006811', 'Escolha o método', 'Use a série conhecida ou calcule derivadas no centro, mantendo a potência e o fatorial correspondentes a cada ordem.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006811' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068111', '40000000-0000-4000-8000-000000006811', 'Desenvolva a estratégia', 'No centro, $f(1)=0$, $f''(1)=1$ e $f''''(1)=-1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006811' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000068112', '40000000-0000-4000-8000-000000006811', 'Complete o cálculo', 'Use potências de $x-1$: o polinômio é $(x-1)-(x-1)^2/2$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006811' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
