insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000062000', '40000000-0000-4000-8000-000000006200', 'Antes de calcular, escolha qual fator fica em $u$. Em geral, prefira o fator que fica mais simples quando derivado.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006200' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
