insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062001', '40000000-0000-4000-8000-000000006200', 'Escolha o método', 'Procure um produto em que derivar um fator o simplifique e integrar o outro seja direto. Esse é o sinal de integração por partes.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006200' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
