insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062033', '40000000-0000-4000-8000-000000006203', 'Desenvolva a estratégia', 'Com $u=x$ e $dv=e^{2x}dx$, temos $v=e^{2x}/2$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006203' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
