insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062053', '40000000-0000-4000-8000-000000006205', 'Desenvolva a estratégia', 'Uma integração por partes resulta em $x^2e^x-2\int xe^x dx$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006205' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062054', '40000000-0000-4000-8000-000000006205', 'Complete o cálculo', 'Repita por partes: $\int xe^x dx=e^x(x-1)$. Substituindo, resulta $e^x(x^2-2x+2)+C$.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006205' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
