insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000062070', '40000000-0000-4000-8000-000000006207', 'Compare os graus do numerador e do denominador; se necessário, faça a divisão polinomial antes das frações parciais.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_hints (id, question_id, content_markdown, sort_order) select '60000000-0000-4000-8000-000000062071', '40000000-0000-4000-8000-000000006207', 'Depois de encontrar os coeficientes, substitua-os de volta na identidade para conferir o numerador.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062070', '40000000-0000-4000-8000-000000006207', 'Prepare a leitura', 'Compare os graus do numerador e do denominador antes de escolher a decomposição.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062071', '40000000-0000-4000-8000-000000006207', 'Escolha o método', 'Transforme a função racional em parcelas mais simples antes de integrar. A decomposição deve ser conferida recompondo o numerador.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062072', '40000000-0000-4000-8000-000000006207', 'Planeje o cálculo', 'Compare os graus do numerador e do denominador; se necessário, faça a divisão polinomial antes das frações parciais.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000062073', '40000000-0000-4000-8000-000000006207', 'Desenvolva a estratégia', 'Decomponha $1/[x(x+1)]=1/x-1/(x+1)$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006207' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
