insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000065092', '40000000-0000-4000-8000-000000006509', 'Planeje o cálculo', 'Escreva o termo geral $a_n$ e calcule seu limite quando $n$ tende ao infinito.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006509' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000065093', '40000000-0000-4000-8000-000000006509', 'Desenvolva a estratégia', 'Decomponha $1/[n(n+1)]=1/n-1/(n+1)$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006509' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
