insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '70000000-0000-4000-8000-000000065113', '40000000-0000-4000-8000-000000006511', 'Desenvolva a estratégia', 'A soma dos logaritmos é o logaritmo do produto. Esse produto até $N$ se simplifica para $2(N+1)/(N+2)$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000006511' and publication_status='draft') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
